<div class="dashboard-heading"><div><span class="eyebrow">ATUALIZAÇÕES</span><h2>Notificações.</h2><p>Acompanhe movimentações importantes da sua conta.</p></div></div><section class="panel notification-list"><?php if(!$notifications):?><div class="empty-state"><span>✓</span><h3>Tudo em dia</h3><p>Você não possui notificações.</p></div><?php endif;?><?php foreach($notifications as $notification):?><a href="<?=e(url($notification['action_url']?:'/minha-conta'))?>" class="<?=empty($notification['read_at'])?'is-unread':''?>"><i></i><div><strong><?=e($notification['title'])?></strong><p><?=e($notification['message'])?></p><small><?=date('d/m/Y H:i',strtotime($notification['created_at']))?></small></div><span>→</span></a><?php endforeach;?></section>
